window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ca6ab24fd67057a1"]={"versions": [{"id": "FIG-ca6ab24fd67057a1", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> PDU-Payload- / Wire-Format-Layoutdiagramm (Bit-/Byte-Ebene-Serialisierungsraster, 64-Bit-Darstellungsbreite).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Padding- und Alignment-Regeln bei der SOME/IP-Serialisierung im AUTOSAR System Template (<code>AUTOSAR_TPS_SystemTemplate</code>, Release 4.3.1).</li>\n<li><strong>Funktionale Einordnung:</strong> Veranschaulicht das gezielte Einfügen von Füllbytes (Padding) in den On-the-Wire-Bytestrom durch den SOME/IP-Transformer (<code>SomeipXf</code>) bzw. Serialisierer, um nachfolgende Datenelemente auf definierte Wortgrenzen (hier: 32-Bit-Alignment) auszurichten. Liegt architektonisch in der Transformationsschicht zwischen RTE/SWC (strukturierte Daten) und der PDU-basierten Kommunikationsschicht (Com / PduR / SoAd).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>SOME/IP Header:</strong> Fester 16-Byte-Protokoll-Header (Message ID, Length, Request ID, Protocol/Interface Version, Message Type, Return Code) vor Beginn des Nutzdaten-Payloads.</li>\n<li><strong>Primitive Datenelemente:</strong></li>\n<li><code>UINT16</code>: 16-Bit-Ganzzahl (2 Bytes, Offset 0–1).</li>\n<li><code>uint8</code>: 8-Bit-Ganzzahlen (1 Byte).</li>\n<li><code>UINT32</code>: 32-Bit-Ganzzahl (4 Bytes, Offset 8–11).</li>\n<li><code>UINT64</code>: 64-Bit-Ganzzahl (8 Bytes, Offset 12–19), überspannt die 64-Bit-Zeilenbegrenzung.</li>\n<li><strong>Dynamische Container / Längenfelder:</strong></li>\n<li><code>Lengthfield (16Bit)</code>: 2-Byte-Längenindikator (<code>sizeOfArrayLengthField</code> = 16 Bit), der die Anzahl der nachfolgenden Nutzdaten-Bytes eines dynamischen Arrays oder Strings angibt.</li>\n<li>Erstes Längenfeld (Zeile 2): Steuert die folgenden 3 × <code>uint8</code> (Nutzdatenlänge = 3 Bytes).</li>\n<li>Zweites Längenfeld (Zeile 4): Steuert die folgenden 8 × <code>uint8</code> (Nutzdatenlänge = 8 Bytes).</li>\n<li><strong>Padding (rot markiert):</strong> 1-Byte-Füllwert (8 Bit, Offset 7).</li>\n<li><strong>Metamodell-Beziehungen (<code>AUTOSAR_TPS_SystemTemplate</code>):</strong></li>\n<li>Konfiguriert über <code>SomeipTransformationProps</code> (aggregiert in <code>TransformationTechnology</code>):</li>\n<li><code>alignment = 32</code> (Bit): Jedes neue Datenfeld/Strukturmitglied muss an einer durch 4 Bytes (32 Bit) teilbaren Adresse beginnen.</li>\n<li><code>sizeOfArrayLengthField = 16</code> (Bit).</li>\n<li><strong>Layout-Berechnung:</strong></li>\n<li>Offset 0–1: <code>UINT16</code> (2 Byte)</li>\n<li>Offset 2–3: <code>Lengthfield</code> (2 Byte)</li>\n<li>Offset 4–6: 3 × <code>uint8</code> (3 Byte) $\\rightarrow$ Summe bis hier: 7 Bytes.</li>\n<li>Nächstes Element ist <code>UINT32</code>, verlangt 32-Bit-Grenze (nächste durch 4 teilbare Adresse ist Offset 8).</li>\n<li>Injektion von 1 Byte <code>Padding</code> an Offset 7 schließt die Lücke auf 8 Bytes.</li>\n<li>Offset 8–11: <code>UINT32</code> (4 Bytes).</li>\n<li>Offset 12–19: <code>UINT64</code> (8 Bytes). Da Offset 12 durch 4 teilbar ist, ist das 32-Bit-Alignment erfüllt – kein Padding vor <code>UINT64</code> erforderlich, obwohl es kein 64-Bit-Alignment besitzt.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\">\n<li><strong>Serialisierung (Sender-Pfad, <code>SomeipXf_Transform</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Serialisierer schreibt statische und dynamische Felder sequenziell in den Sendepuffer.</li>\n<li>Nach Schreiben des dritten <code>uint8</code> des ersten Arrays beträgt der Schreibzeiger 7 Bytes.</li>\n<li>Prüflogik evaluiert das konfigurierte Alignment des Zieltyps (<code>UINT32</code>, 32 Bit): <code>Offset % 4 != 0</code> (7 mod 4 = 3).</li>\n<li>Serialisierer injiziert $4 - 3 = 1$ Padding-Byte (Default: <code>0x00</code>) in den Puffer; Schreibzeiger inkrementiert auf Offset 8.</li>\n<li><code>UINT32</code> wird ab Offset 8 geschrieben; anschließendes <code>UINT64</code> wird ab Offset 12 geschrieben (12 mod 4 = 0, kein Padding).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Deserialisierung (Empfänger-Pfad, <code>SomeipXf_InvTransform</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Parser liest <code>Lengthfield (16Bit)</code> mit Wert <code>3</code> und konsumiert exakt 3 Bytes <code>uint8</code>.</li>\n<li>Vor dem Dekodieren des nachfolgenden Signals (<code>UINT32</code>) berechnet der Parser die erwartete Alignment-Grenze (32 Bit) und überspringt das Padding-Byte (Offset 7).</li>\n<li>Lesezeiger springt direkt auf Offset 8 zur Extraktion des <code>UINT32</code>.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Längenfeld-Semantik:</strong> Das Padding-Byte zählt <strong>nicht</strong> zur Nutzdatenlänge des dynamischen Arrays. Der Wert im <code>Lengthfield (16Bit)</code> muss strikt <code>3</code> sein (nicht <code>4</code>). Ein Mitzählen von Alignment-Bytes im Längenfeld verletzt die SOME/IP-Spezifikation (<code>PRS_SOMEIPProtocol</code>).</li>\n<li><strong>Interoperabilität & ARXML-Konsistenz:</strong> Sender und Empfänger (Classic Platform SWC, Adaptive Platform Service Instance via <code>ara::com</code> oder Linux-Third-Party-Stacks wie <code>vsomeip</code>) müssen identische <code>SomeipTransformationProps.alignment</code>-Werte aufweisen. Weicht die Konfiguration ab (z. B. Sender ohne Alignment/<code>0</code>, Empfänger mit <code>32 Bit</code>), verschieben sich alle nachfolgenden Signale um 1 Byte, was zu schwer lokalisierbaren Deserialisierungs- und Datendefekten führt.</li>\n<li><strong>MCU-Architektur & Performance:</strong> 32-Bit- und 64-Bit-Mikrocontroller (z. B. Infineon AURIX TC3xx/TC4xx, ARM Cortex-R/Cortex-A) profitieren bei 32-Bit-ausgerichtetem Wire-Format von reduzierten Shift-/Maskierungsoperationen. Für hardwarebeschleunigten Zero-Copy-Zugriff muss zusätzlich sichergestellt werden, dass der Start des Ethernet-Payloads (nach IP/UDP- bzw. TCP- und SOME/IP-Header) im RAM 32-Bit-aligned allokiert ist.</li>\n<li><strong>Padding-Byte-Inhalt:</strong> Gemäß SOME/IP-Standard ist der Inhalt von Padding-Bytes senderseitig mit Nullen (<code>0x00</code>) zu belegen; empfängerseitig müssen die Padding-Bytes ignoriert und dürfen nicht auf statische Werte validiert werden.</li>\n</ul>"}, {"id": "FIG-dfcce4d31b876bf1", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> PDU-Payload- / Wire-Format-Layoutdiagramm (Bit-/Byte-Ebene-Serialisierungsraster, 64-Bit-Darstellungsbreite).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Padding- und Alignment-Regeln bei der SOME/IP-Serialisierung im AUTOSAR System Template (<code>AUTOSAR_TPS_SystemTemplate</code>, Release 4.3.1).</li>\n<li><strong>Funktionale Einordnung:</strong> Veranschaulicht das gezielte Einfügen von Füllbytes (Padding) in den On-the-Wire-Bytestrom durch den SOME/IP-Transformer (<code>SomeipXf</code>) bzw. Serialisierer, um nachfolgende Datenelemente auf definierte Wortgrenzen (hier: 32-Bit-Alignment) auszurichten. Liegt architektonisch in der Transformationsschicht zwischen RTE/SWC (strukturierte Daten) und der PDU-basierten Kommunikationsschicht (Com / PduR / SoAd).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>SOME/IP Header:</strong> Fester 16-Byte-Protokoll-Header (Message ID, Length, Request ID, Protocol/Interface Version, Message Type, Return Code) vor Beginn des Nutzdaten-Payloads.</li>\n<li><strong>Primitive Datenelemente:</strong></li>\n<li><code>UINT16</code>: 16-Bit-Ganzzahl (2 Bytes, Offset 0–1).</li>\n<li><code>uint8</code>: 8-Bit-Ganzzahlen (1 Byte).</li>\n<li><code>UINT32</code>: 32-Bit-Ganzzahl (4 Bytes, Offset 8–11).</li>\n<li><code>UINT64</code>: 64-Bit-Ganzzahl (8 Bytes, Offset 12–19), überspannt die 64-Bit-Zeilenbegrenzung.</li>\n<li><strong>Dynamische Container / Längenfelder:</strong></li>\n<li><code>Lengthfield (16Bit)</code>: 2-Byte-Längenindikator (<code>sizeOfArrayLengthField</code> = 16 Bit), der die Anzahl der nachfolgenden Nutzdaten-Bytes eines dynamischen Arrays oder Strings angibt.</li>\n<li>Erstes Längenfeld (Zeile 2): Steuert die folgenden 3 × <code>uint8</code> (Nutzdatenlänge = 3 Bytes).</li>\n<li>Zweites Längenfeld (Zeile 4): Steuert die folgenden 8 × <code>uint8</code> (Nutzdatenlänge = 8 Bytes).</li>\n<li><strong>Padding (rot markiert):</strong> 1-Byte-Füllwert (8 Bit, Offset 7).</li>\n<li><strong>Metamodell-Beziehungen (<code>AUTOSAR_TPS_SystemTemplate</code>):</strong></li>\n<li>Konfiguriert über <code>SomeipTransformationProps</code> (aggregiert in <code>TransformationTechnology</code>):</li>\n<li><code>alignment = 32</code> (Bit): Jedes neue Datenfeld/Strukturmitglied muss an einer durch 4 Bytes (32 Bit) teilbaren Adresse beginnen.</li>\n<li><code>sizeOfArrayLengthField = 16</code> (Bit).</li>\n<li><strong>Layout-Berechnung:</strong></li>\n<li>Offset 0–1: <code>UINT16</code> (2 Byte)</li>\n<li>Offset 2–3: <code>Lengthfield</code> (2 Byte)</li>\n<li>Offset 4–6: 3 × <code>uint8</code> (3 Byte) $\\rightarrow$ Summe bis hier: 7 Bytes.</li>\n<li>Nächstes Element ist <code>UINT32</code>, verlangt 32-Bit-Grenze (nächste durch 4 teilbare Adresse ist Offset 8).</li>\n<li>Injektion von 1 Byte <code>Padding</code> an Offset 7 schließt die Lücke auf 8 Bytes.</li>\n<li>Offset 8–11: <code>UINT32</code> (4 Bytes).</li>\n<li>Offset 12–19: <code>UINT64</code> (8 Bytes). Da Offset 12 durch 4 teilbar ist, ist das 32-Bit-Alignment erfüllt – kein Padding vor <code>UINT64</code> erforderlich, obwohl es kein 64-Bit-Alignment besitzt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Serialisierung (Sender-Pfad, <code>SomeipXf_Transform</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Serialisierer schreibt statische und dynamische Felder sequenziell in den Sendepuffer.</li>\n<li>Nach Schreiben des dritten <code>uint8</code> des ersten Arrays beträgt der Schreibzeiger 7 Bytes.</li>\n<li>Prüflogik evaluiert das konfigurierte Alignment des Zieltyps (<code>UINT32</code>, 32 Bit): <code>Offset % 4 != 0</code> (7 mod 4 = 3).</li>\n<li>Serialisierer injiziert $4 - 3 = 1$ Padding-Byte (Default: <code>0x00</code>) in den Puffer; Schreibzeiger inkrementiert auf Offset 8.</li>\n<li><code>UINT32</code> wird ab Offset 8 geschrieben; anschließendes <code>UINT64</code> wird ab Offset 12 geschrieben (12 mod 4 = 0, kein Padding).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Deserialisierung (Empfänger-Pfad, <code>SomeipXf_InvTransform</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Parser liest <code>Lengthfield (16Bit)</code> mit Wert <code>3</code> und konsumiert exakt 3 Bytes <code>uint8</code>.</li>\n<li>Vor dem Dekodieren des nachfolgenden Signals (<code>UINT32</code>) berechnet der Parser die erwartete Alignment-Grenze (32 Bit) und überspringt das Padding-Byte (Offset 7).</li>\n<li>Lesezeiger springt direkt auf Offset 8 zur Extraktion des <code>UINT32</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Längenfeld-Semantik:</strong> Das Padding-Byte zählt <strong>nicht</strong> zur Nutzdatenlänge des dynamischen Arrays. Der Wert im <code>Lengthfield (16Bit)</code> muss strikt <code>3</code> sein (nicht <code>4</code>). Ein Mitzählen von Alignment-Bytes im Längenfeld verletzt die SOME/IP-Spezifikation (<code>PRS_SOMEIPProtocol</code>).</li>\n<li><strong>Interoperabilität & ARXML-Konsistenz:</strong> Sender und Empfänger (Classic Platform SWC, Adaptive Platform Service Instance via <code>ara::com</code> oder Linux-Third-Party-Stacks wie <code>vsomeip</code>) müssen identische <code>SomeipTransformationProps.alignment</code>-Werte aufweisen. Weicht die Konfiguration ab (z. B. Sender ohne Alignment/<code>0</code>, Empfänger mit <code>32 Bit</code>), verschieben sich alle nachfolgenden Signale um 1 Byte, was zu schwer lokalisierbaren Deserialisierungs- und Datendefekten führt.</li>\n<li><strong>MCU-Architektur & Performance:</strong> 32-Bit- und 64-Bit-Mikrocontroller (z. B. Infineon AURIX TC3xx/TC4xx, ARM Cortex-R/Cortex-A) profitieren bei 32-Bit-ausgerichtetem Wire-Format von reduzierten Shift-/Maskierungsoperationen. Für hardwarebeschleunigten Zero-Copy-Zugriff muss zusätzlich sichergestellt werden, dass der Start des Ethernet-Payloads (nach IP/UDP- bzw. TCP- und SOME/IP-Header) im RAM 32-Bit-aligned allokiert ist.</li>\n<li><strong>Padding-Byte-Inhalt:</strong> Gemäß SOME/IP-Standard ist der Inhalt von Padding-Bytes senderseitig mit Nullen (<code>0x00</code>) zu belegen; empfängerseitig müssen die Padding-Bytes ignoriert und dürfen nicht auf statische Werte validiert werden.</li>\n</ul>"}, {"id": "FIG-bdfb59c77a572ecf", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> PDU-Payload- / Wire-Format-Layoutdiagramm (Bit-/Byte-Ebene-Serialisierungsraster, 64-Bit-Darstellungsbreite).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Padding- und Alignment-Regeln bei der SOME/IP-Serialisierung im AUTOSAR System Template (<code>AUTOSAR_TPS_SystemTemplate</code>, Release 4.3.1).</li>\n<li><strong>Funktionale Einordnung:</strong> Veranschaulicht das gezielte Einfügen von Füllbytes (Padding) in den On-the-Wire-Bytestrom durch den SOME/IP-Transformer (<code>SomeipXf</code>) bzw. Serialisierer, um nachfolgende Datenelemente auf definierte Wortgrenzen (hier: 32-Bit-Alignment) auszurichten. Liegt architektonisch in der Transformationsschicht zwischen RTE/SWC (strukturierte Daten) und der PDU-basierten Kommunikationsschicht (Com / PduR / SoAd).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>SOME/IP Header:</strong> Fester 16-Byte-Protokoll-Header (Message ID, Length, Request ID, Protocol/Interface Version, Message Type, Return Code) vor Beginn des Nutzdaten-Payloads.</li>\n<li><strong>Primitive Datenelemente:</strong></li>\n<li><code>UINT16</code>: 16-Bit-Ganzzahl (2 Bytes, Offset 0–1).</li>\n<li><code>uint8</code>: 8-Bit-Ganzzahlen (1 Byte).</li>\n<li><code>UINT32</code>: 32-Bit-Ganzzahl (4 Bytes, Offset 8–11).</li>\n<li><code>UINT64</code>: 64-Bit-Ganzzahl (8 Bytes, Offset 12–19), überspannt die 64-Bit-Zeilenbegrenzung.</li>\n<li><strong>Dynamische Container / Längenfelder:</strong></li>\n<li><code>Lengthfield (16Bit)</code>: 2-Byte-Längenindikator (<code>sizeOfArrayLengthField</code> = 16 Bit), der die Anzahl der nachfolgenden Nutzdaten-Bytes eines dynamischen Arrays oder Strings angibt.</li>\n<li>Erstes Längenfeld (Zeile 2): Steuert die folgenden 3 × <code>uint8</code> (Nutzdatenlänge = 3 Bytes).</li>\n<li>Zweites Längenfeld (Zeile 4): Steuert die folgenden 8 × <code>uint8</code> (Nutzdatenlänge = 8 Bytes).</li>\n<li><strong>Padding (rot markiert):</strong> 1-Byte-Füllwert (8 Bit, Offset 7).</li>\n<li><strong>Metamodell-Beziehungen (<code>AUTOSAR_TPS_SystemTemplate</code>):</strong></li>\n<li>Konfiguriert über <code>SomeipTransformationProps</code> (aggregiert in <code>TransformationTechnology</code>):</li>\n<li><code>alignment = 32</code> (Bit): Jedes neue Datenfeld/Strukturmitglied muss an einer durch 4 Bytes (32 Bit) teilbaren Adresse beginnen.</li>\n<li><code>sizeOfArrayLengthField = 16</code> (Bit).</li>\n<li><strong>Layout-Berechnung:</strong></li>\n<li>Offset 0–1: <code>UINT16</code> (2 Byte)</li>\n<li>Offset 2–3: <code>Lengthfield</code> (2 Byte)</li>\n<li>Offset 4–6: 3 × <code>uint8</code> (3 Byte) $\\rightarrow$ Summe bis hier: 7 Bytes.</li>\n<li>Nächstes Element ist <code>UINT32</code>, verlangt 32-Bit-Grenze (nächste durch 4 teilbare Adresse ist Offset 8).</li>\n<li>Injektion von 1 Byte <code>Padding</code> an Offset 7 schließt die Lücke auf 8 Bytes.</li>\n<li>Offset 8–11: <code>UINT32</code> (4 Bytes).</li>\n<li>Offset 12–19: <code>UINT64</code> (8 Bytes). Da Offset 12 durch 4 teilbar ist, ist das 32-Bit-Alignment erfüllt – kein Padding vor <code>UINT64</code> erforderlich, obwohl es kein 64-Bit-Alignment besitzt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Serialisierung (Sender-Pfad, <code>SomeipXf_Transform</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Serialisierer schreibt statische und dynamische Felder sequenziell in den Sendepuffer.</li>\n<li>Nach Schreiben des dritten <code>uint8</code> des ersten Arrays beträgt der Schreibzeiger 7 Bytes.</li>\n<li>Prüflogik evaluiert das konfigurierte Alignment des Zieltyps (<code>UINT32</code>, 32 Bit): <code>Offset % 4 != 0</code> (7 mod 4 = 3).</li>\n<li>Serialisierer injiziert $4 - 3 = 1$ Padding-Byte (Default: <code>0x00</code>) in den Puffer; Schreibzeiger inkrementiert auf Offset 8.</li>\n<li><code>UINT32</code> wird ab Offset 8 geschrieben; anschließendes <code>UINT64</code> wird ab Offset 12 geschrieben (12 mod 4 = 0, kein Padding).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Deserialisierung (Empfänger-Pfad, <code>SomeipXf_InvTransform</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Parser liest <code>Lengthfield (16Bit)</code> mit Wert <code>3</code> und konsumiert exakt 3 Bytes <code>uint8</code>.</li>\n<li>Vor dem Dekodieren des nachfolgenden Signals (<code>UINT32</code>) berechnet der Parser die erwartete Alignment-Grenze (32 Bit) und überspringt das Padding-Byte (Offset 7).</li>\n<li>Lesezeiger springt direkt auf Offset 8 zur Extraktion des <code>UINT32</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Längenfeld-Semantik:</strong> Das Padding-Byte zählt <strong>nicht</strong> zur Nutzdatenlänge des dynamischen Arrays. Der Wert im <code>Lengthfield (16Bit)</code> muss strikt <code>3</code> sein (nicht <code>4</code>). Ein Mitzählen von Alignment-Bytes im Längenfeld verletzt die SOME/IP-Spezifikation (<code>PRS_SOMEIPProtocol</code>).</li>\n<li><strong>Interoperabilität & ARXML-Konsistenz:</strong> Sender und Empfänger (Classic Platform SWC, Adaptive Platform Service Instance via <code>ara::com</code> oder Linux-Third-Party-Stacks wie <code>vsomeip</code>) müssen identische <code>SomeipTransformationProps.alignment</code>-Werte aufweisen. Weicht die Konfiguration ab (z. B. Sender ohne Alignment/<code>0</code>, Empfänger mit <code>32 Bit</code>), verschieben sich alle nachfolgenden Signale um 1 Byte, was zu schwer lokalisierbaren Deserialisierungs- und Datendefekten führt.</li>\n<li><strong>MCU-Architektur & Performance:</strong> 32-Bit- und 64-Bit-Mikrocontroller (z. B. Infineon AURIX TC3xx/TC4xx, ARM Cortex-R/Cortex-A) profitieren bei 32-Bit-ausgerichtetem Wire-Format von reduzierten Shift-/Maskierungsoperationen. Für hardwarebeschleunigten Zero-Copy-Zugriff muss zusätzlich sichergestellt werden, dass der Start des Ethernet-Payloads (nach IP/UDP- bzw. TCP- und SOME/IP-Header) im RAM 32-Bit-aligned allokiert ist.</li>\n<li><strong>Padding-Byte-Inhalt:</strong> Gemäß SOME/IP-Standard ist der Inhalt von Padding-Bytes senderseitig mit Nullen (<code>0x00</code>) zu belegen; empfängerseitig müssen die Padding-Bytes ignoriert und dürfen nicht auf statische Werte validiert werden.</li>\n</ul>"}, {"id": "FIG-8efaf0c350863cb2", "releases": ["R22-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> PDU-Payload- / Wire-Format-Layoutdiagramm (Bit-/Byte-Ebene-Serialisierungsraster, 64-Bit-Darstellungsbreite).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Padding- und Alignment-Regeln bei der SOME/IP-Serialisierung im AUTOSAR System Template (<code>AUTOSAR_TPS_SystemTemplate</code>, Release 4.3.1).</li>\n<li><strong>Funktionale Einordnung:</strong> Veranschaulicht das gezielte Einfügen von Füllbytes (Padding) in den On-the-Wire-Bytestrom durch den SOME/IP-Transformer (<code>SomeipXf</code>) bzw. Serialisierer, um nachfolgende Datenelemente auf definierte Wortgrenzen (hier: 32-Bit-Alignment) auszurichten. Liegt architektonisch in der Transformationsschicht zwischen RTE/SWC (strukturierte Daten) und der PDU-basierten Kommunikationsschicht (Com / PduR / SoAd).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>SOME/IP Header:</strong> Fester 16-Byte-Protokoll-Header (Message ID, Length, Request ID, Protocol/Interface Version, Message Type, Return Code) vor Beginn des Nutzdaten-Payloads.</li>\n<li><strong>Primitive Datenelemente:</strong></li>\n<li><code>UINT16</code>: 16-Bit-Ganzzahl (2 Bytes, Offset 0–1).</li>\n<li><code>uint8</code>: 8-Bit-Ganzzahlen (1 Byte).</li>\n<li><code>UINT32</code>: 32-Bit-Ganzzahl (4 Bytes, Offset 8–11).</li>\n<li><code>UINT64</code>: 64-Bit-Ganzzahl (8 Bytes, Offset 12–19), überspannt die 64-Bit-Zeilenbegrenzung.</li>\n<li><strong>Dynamische Container / Längenfelder:</strong></li>\n<li><code>Lengthfield (16Bit)</code>: 2-Byte-Längenindikator (<code>sizeOfArrayLengthField</code> = 16 Bit), der die Anzahl der nachfolgenden Nutzdaten-Bytes eines dynamischen Arrays oder Strings angibt.</li>\n<li>Erstes Längenfeld (Zeile 2): Steuert die folgenden 3 × <code>uint8</code> (Nutzdatenlänge = 3 Bytes).</li>\n<li>Zweites Längenfeld (Zeile 4): Steuert die folgenden 8 × <code>uint8</code> (Nutzdatenlänge = 8 Bytes).</li>\n<li><strong>Padding (rot markiert):</strong> 1-Byte-Füllwert (8 Bit, Offset 7).</li>\n<li><strong>Metamodell-Beziehungen (<code>AUTOSAR_TPS_SystemTemplate</code>):</strong></li>\n<li>Konfiguriert über <code>SomeipTransformationProps</code> (aggregiert in <code>TransformationTechnology</code>):</li>\n<li><code>alignment = 32</code> (Bit): Jedes neue Datenfeld/Strukturmitglied muss an einer durch 4 Bytes (32 Bit) teilbaren Adresse beginnen.</li>\n<li><code>sizeOfArrayLengthField = 16</code> (Bit).</li>\n<li><strong>Layout-Berechnung:</strong></li>\n<li>Offset 0–1: <code>UINT16</code> (2 Byte)</li>\n<li>Offset 2–3: <code>Lengthfield</code> (2 Byte)</li>\n<li>Offset 4–6: 3 × <code>uint8</code> (3 Byte) $\\rightarrow$ Summe bis hier: 7 Bytes.</li>\n<li>Nächstes Element ist <code>UINT32</code>, verlangt 32-Bit-Grenze (nächste durch 4 teilbare Adresse ist Offset 8).</li>\n<li>Injektion von 1 Byte <code>Padding</code> an Offset 7 schließt die Lücke auf 8 Bytes.</li>\n<li>Offset 8–11: <code>UINT32</code> (4 Bytes).</li>\n<li>Offset 12–19: <code>UINT64</code> (8 Bytes). Da Offset 12 durch 4 teilbar ist, ist das 32-Bit-Alignment erfüllt – kein Padding vor <code>UINT64</code> erforderlich, obwohl es kein 64-Bit-Alignment besitzt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Serialisierung (Sender-Pfad, <code>SomeipXf_Transform</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Serialisierer schreibt statische und dynamische Felder sequenziell in den Sendepuffer.</li>\n<li>Nach Schreiben des dritten <code>uint8</code> des ersten Arrays beträgt der Schreibzeiger 7 Bytes.</li>\n<li>Prüflogik evaluiert das konfigurierte Alignment des Zieltyps (<code>UINT32</code>, 32 Bit): <code>Offset % 4 != 0</code> (7 mod 4 = 3).</li>\n<li>Serialisierer injiziert $4 - 3 = 1$ Padding-Byte (Default: <code>0x00</code>) in den Puffer; Schreibzeiger inkrementiert auf Offset 8.</li>\n<li><code>UINT32</code> wird ab Offset 8 geschrieben; anschließendes <code>UINT64</code> wird ab Offset 12 geschrieben (12 mod 4 = 0, kein Padding).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Deserialisierung (Empfänger-Pfad, <code>SomeipXf_InvTransform</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Parser liest <code>Lengthfield (16Bit)</code> mit Wert <code>3</code> und konsumiert exakt 3 Bytes <code>uint8</code>.</li>\n<li>Vor dem Dekodieren des nachfolgenden Signals (<code>UINT32</code>) berechnet der Parser die erwartete Alignment-Grenze (32 Bit) und überspringt das Padding-Byte (Offset 7).</li>\n<li>Lesezeiger springt direkt auf Offset 8 zur Extraktion des <code>UINT32</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Längenfeld-Semantik:</strong> Das Padding-Byte zählt <strong>nicht</strong> zur Nutzdatenlänge des dynamischen Arrays. Der Wert im <code>Lengthfield (16Bit)</code> muss strikt <code>3</code> sein (nicht <code>4</code>). Ein Mitzählen von Alignment-Bytes im Längenfeld verletzt die SOME/IP-Spezifikation (<code>PRS_SOMEIPProtocol</code>).</li>\n<li><strong>Interoperabilität & ARXML-Konsistenz:</strong> Sender und Empfänger (Classic Platform SWC, Adaptive Platform Service Instance via <code>ara::com</code> oder Linux-Third-Party-Stacks wie <code>vsomeip</code>) müssen identische <code>SomeipTransformationProps.alignment</code>-Werte aufweisen. Weicht die Konfiguration ab (z. B. Sender ohne Alignment/<code>0</code>, Empfänger mit <code>32 Bit</code>), verschieben sich alle nachfolgenden Signale um 1 Byte, was zu schwer lokalisierbaren Deserialisierungs- und Datendefekten führt.</li>\n<li><strong>MCU-Architektur & Performance:</strong> 32-Bit- und 64-Bit-Mikrocontroller (z. B. Infineon AURIX TC3xx/TC4xx, ARM Cortex-R/Cortex-A) profitieren bei 32-Bit-ausgerichtetem Wire-Format von reduzierten Shift-/Maskierungsoperationen. Für hardwarebeschleunigten Zero-Copy-Zugriff muss zusätzlich sichergestellt werden, dass der Start des Ethernet-Payloads (nach IP/UDP- bzw. TCP- und SOME/IP-Header) im RAM 32-Bit-aligned allokiert ist.</li>\n<li><strong>Padding-Byte-Inhalt:</strong> Gemäß SOME/IP-Standard ist der Inhalt von Padding-Bytes senderseitig mit Nullen (<code>0x00</code>) zu belegen; empfängerseitig müssen die Padding-Bytes ignoriert und dürfen nicht auf statische Werte validiert werden.</li>\n</ul>"}, {"id": "FIG-be371d2e6582e11d", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> PDU-Payload- / Wire-Format-Layoutdiagramm (Bit-/Byte-Ebene-Serialisierungsraster, 64-Bit-Darstellungsbreite).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Padding- und Alignment-Regeln bei der SOME/IP-Serialisierung im AUTOSAR System Template (<code>AUTOSAR_TPS_SystemTemplate</code>, Release 4.3.1).</li>\n<li><strong>Funktionale Einordnung:</strong> Veranschaulicht das gezielte Einfügen von Füllbytes (Padding) in den On-the-Wire-Bytestrom durch den SOME/IP-Transformer (<code>SomeipXf</code>) bzw. Serialisierer, um nachfolgende Datenelemente auf definierte Wortgrenzen (hier: 32-Bit-Alignment) auszurichten. Liegt architektonisch in der Transformationsschicht zwischen RTE/SWC (strukturierte Daten) und der PDU-basierten Kommunikationsschicht (Com / PduR / SoAd).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>SOME/IP Header:</strong> Fester 16-Byte-Protokoll-Header (Message ID, Length, Request ID, Protocol/Interface Version, Message Type, Return Code) vor Beginn des Nutzdaten-Payloads.</li>\n<li><strong>Primitive Datenelemente:</strong></li>\n<li><code>UINT16</code>: 16-Bit-Ganzzahl (2 Bytes, Offset 0–1).</li>\n<li><code>uint8</code>: 8-Bit-Ganzzahlen (1 Byte).</li>\n<li><code>UINT32</code>: 32-Bit-Ganzzahl (4 Bytes, Offset 8–11).</li>\n<li><code>UINT64</code>: 64-Bit-Ganzzahl (8 Bytes, Offset 12–19), überspannt die 64-Bit-Zeilenbegrenzung.</li>\n<li><strong>Dynamische Container / Längenfelder:</strong></li>\n<li><code>Lengthfield (16Bit)</code>: 2-Byte-Längenindikator (<code>sizeOfArrayLengthField</code> = 16 Bit), der die Anzahl der nachfolgenden Nutzdaten-Bytes eines dynamischen Arrays oder Strings angibt.</li>\n<li>Erstes Längenfeld (Zeile 2): Steuert die folgenden 3 × <code>uint8</code> (Nutzdatenlänge = 3 Bytes).</li>\n<li>Zweites Längenfeld (Zeile 4): Steuert die folgenden 8 × <code>uint8</code> (Nutzdatenlänge = 8 Bytes).</li>\n<li><strong>Padding (rot markiert):</strong> 1-Byte-Füllwert (8 Bit, Offset 7).</li>\n<li><strong>Metamodell-Beziehungen (<code>AUTOSAR_TPS_SystemTemplate</code>):</strong></li>\n<li>Konfiguriert über <code>SomeipTransformationProps</code> (aggregiert in <code>TransformationTechnology</code>):</li>\n<li><code>alignment = 32</code> (Bit): Jedes neue Datenfeld/Strukturmitglied muss an einer durch 4 Bytes (32 Bit) teilbaren Adresse beginnen.</li>\n<li><code>sizeOfArrayLengthField = 16</code> (Bit).</li>\n<li><strong>Layout-Berechnung:</strong></li>\n<li>Offset 0–1: <code>UINT16</code> (2 Byte)</li>\n<li>Offset 2–3: <code>Lengthfield</code> (2 Byte)</li>\n<li>Offset 4–6: 3 × <code>uint8</code> (3 Byte) $\\rightarrow$ Summe bis hier: 7 Bytes.</li>\n<li>Nächstes Element ist <code>UINT32</code>, verlangt 32-Bit-Grenze (nächste durch 4 teilbare Adresse ist Offset 8).</li>\n<li>Injektion von 1 Byte <code>Padding</code> an Offset 7 schließt die Lücke auf 8 Bytes.</li>\n<li>Offset 8–11: <code>UINT32</code> (4 Bytes).</li>\n<li>Offset 12–19: <code>UINT64</code> (8 Bytes). Da Offset 12 durch 4 teilbar ist, ist das 32-Bit-Alignment erfüllt – kein Padding vor <code>UINT64</code> erforderlich, obwohl es kein 64-Bit-Alignment besitzt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Serialisierung (Sender-Pfad, <code>SomeipXf_Transform</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Serialisierer schreibt statische und dynamische Felder sequenziell in den Sendepuffer.</li>\n<li>Nach Schreiben des dritten <code>uint8</code> des ersten Arrays beträgt der Schreibzeiger 7 Bytes.</li>\n<li>Prüflogik evaluiert das konfigurierte Alignment des Zieltyps (<code>UINT32</code>, 32 Bit): <code>Offset % 4 != 0</code> (7 mod 4 = 3).</li>\n<li>Serialisierer injiziert $4 - 3 = 1$ Padding-Byte (Default: <code>0x00</code>) in den Puffer; Schreibzeiger inkrementiert auf Offset 8.</li>\n<li><code>UINT32</code> wird ab Offset 8 geschrieben; anschließendes <code>UINT64</code> wird ab Offset 12 geschrieben (12 mod 4 = 0, kein Padding).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Deserialisierung (Empfänger-Pfad, <code>SomeipXf_InvTransform</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Parser liest <code>Lengthfield (16Bit)</code> mit Wert <code>3</code> und konsumiert exakt 3 Bytes <code>uint8</code>.</li>\n<li>Vor dem Dekodieren des nachfolgenden Signals (<code>UINT32</code>) berechnet der Parser die erwartete Alignment-Grenze (32 Bit) und überspringt das Padding-Byte (Offset 7).</li>\n<li>Lesezeiger springt direkt auf Offset 8 zur Extraktion des <code>UINT32</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Längenfeld-Semantik:</strong> Das Padding-Byte zählt <strong>nicht</strong> zur Nutzdatenlänge des dynamischen Arrays. Der Wert im <code>Lengthfield (16Bit)</code> muss strikt <code>3</code> sein (nicht <code>4</code>). Ein Mitzählen von Alignment-Bytes im Längenfeld verletzt die SOME/IP-Spezifikation (<code>PRS_SOMEIPProtocol</code>).</li>\n<li><strong>Interoperabilität & ARXML-Konsistenz:</strong> Sender und Empfänger (Classic Platform SWC, Adaptive Platform Service Instance via <code>ara::com</code> oder Linux-Third-Party-Stacks wie <code>vsomeip</code>) müssen identische <code>SomeipTransformationProps.alignment</code>-Werte aufweisen. Weicht die Konfiguration ab (z. B. Sender ohne Alignment/<code>0</code>, Empfänger mit <code>32 Bit</code>), verschieben sich alle nachfolgenden Signale um 1 Byte, was zu schwer lokalisierbaren Deserialisierungs- und Datendefekten führt.</li>\n<li><strong>MCU-Architektur & Performance:</strong> 32-Bit- und 64-Bit-Mikrocontroller (z. B. Infineon AURIX TC3xx/TC4xx, ARM Cortex-R/Cortex-A) profitieren bei 32-Bit-ausgerichtetem Wire-Format von reduzierten Shift-/Maskierungsoperationen. Für hardwarebeschleunigten Zero-Copy-Zugriff muss zusätzlich sichergestellt werden, dass der Start des Ethernet-Payloads (nach IP/UDP- bzw. TCP- und SOME/IP-Header) im RAM 32-Bit-aligned allokiert ist.</li>\n<li><strong>Padding-Byte-Inhalt:</strong> Gemäß SOME/IP-Standard ist der Inhalt von Padding-Bytes senderseitig mit Nullen (<code>0x00</code>) zu belegen; empfängerseitig müssen die Padding-Bytes ignoriert und dürfen nicht auf statische Werte validiert werden.</li>\n</ul>"}, {"id": "FIG-421ce26007412e4d", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> PDU-Payload- / Wire-Format-Layoutdiagramm (Bit-/Byte-Ebene-Serialisierungsraster, 64-Bit-Darstellungsbreite).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Padding- und Alignment-Regeln bei der SOME/IP-Serialisierung im AUTOSAR System Template (<code>AUTOSAR_TPS_SystemTemplate</code>, Release 4.3.1).</li>\n<li><strong>Funktionale Einordnung:</strong> Veranschaulicht das gezielte Einfügen von Füllbytes (Padding) in den On-the-Wire-Bytestrom durch den SOME/IP-Transformer (<code>SomeipXf</code>) bzw. Serialisierer, um nachfolgende Datenelemente auf definierte Wortgrenzen (hier: 32-Bit-Alignment) auszurichten. Liegt architektonisch in der Transformationsschicht zwischen RTE/SWC (strukturierte Daten) und der PDU-basierten Kommunikationsschicht (Com / PduR / SoAd).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>SOME/IP Header:</strong> Fester 16-Byte-Protokoll-Header (Message ID, Length, Request ID, Protocol/Interface Version, Message Type, Return Code) vor Beginn des Nutzdaten-Payloads.</li>\n<li><strong>Primitive Datenelemente:</strong></li>\n<li><code>UINT16</code>: 16-Bit-Ganzzahl (2 Bytes, Offset 0–1).</li>\n<li><code>uint8</code>: 8-Bit-Ganzzahlen (1 Byte).</li>\n<li><code>UINT32</code>: 32-Bit-Ganzzahl (4 Bytes, Offset 8–11).</li>\n<li><code>UINT64</code>: 64-Bit-Ganzzahl (8 Bytes, Offset 12–19), überspannt die 64-Bit-Zeilenbegrenzung.</li>\n<li><strong>Dynamische Container / Längenfelder:</strong></li>\n<li><code>Lengthfield (16Bit)</code>: 2-Byte-Längenindikator (<code>sizeOfArrayLengthField</code> = 16 Bit), der die Anzahl der nachfolgenden Nutzdaten-Bytes eines dynamischen Arrays oder Strings angibt.</li>\n<li>Erstes Längenfeld (Zeile 2): Steuert die folgenden 3 × <code>uint8</code> (Nutzdatenlänge = 3 Bytes).</li>\n<li>Zweites Längenfeld (Zeile 4): Steuert die folgenden 8 × <code>uint8</code> (Nutzdatenlänge = 8 Bytes).</li>\n<li><strong>Padding (rot markiert):</strong> 1-Byte-Füllwert (8 Bit, Offset 7).</li>\n<li><strong>Metamodell-Beziehungen (<code>AUTOSAR_TPS_SystemTemplate</code>):</strong></li>\n<li>Konfiguriert über <code>SomeipTransformationProps</code> (aggregiert in <code>TransformationTechnology</code>):</li>\n<li><code>alignment = 32</code> (Bit): Jedes neue Datenfeld/Strukturmitglied muss an einer durch 4 Bytes (32 Bit) teilbaren Adresse beginnen.</li>\n<li><code>sizeOfArrayLengthField = 16</code> (Bit).</li>\n<li><strong>Layout-Berechnung:</strong></li>\n<li>Offset 0–1: <code>UINT16</code> (2 Byte)</li>\n<li>Offset 2–3: <code>Lengthfield</code> (2 Byte)</li>\n<li>Offset 4–6: 3 × <code>uint8</code> (3 Byte) $\\rightarrow$ Summe bis hier: 7 Bytes.</li>\n<li>Nächstes Element ist <code>UINT32</code>, verlangt 32-Bit-Grenze (nächste durch 4 teilbare Adresse ist Offset 8).</li>\n<li>Injektion von 1 Byte <code>Padding</code> an Offset 7 schließt die Lücke auf 8 Bytes.</li>\n<li>Offset 8–11: <code>UINT32</code> (4 Bytes).</li>\n<li>Offset 12–19: <code>UINT64</code> (8 Bytes). Da Offset 12 durch 4 teilbar ist, ist das 32-Bit-Alignment erfüllt – kein Padding vor <code>UINT64</code> erforderlich, obwohl es kein 64-Bit-Alignment besitzt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Serialisierung (Sender-Pfad, <code>SomeipXf_Transform</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Serialisierer schreibt statische und dynamische Felder sequenziell in den Sendepuffer.</li>\n<li>Nach Schreiben des dritten <code>uint8</code> des ersten Arrays beträgt der Schreibzeiger 7 Bytes.</li>\n<li>Prüflogik evaluiert das konfigurierte Alignment des Zieltyps (<code>UINT32</code>, 32 Bit): <code>Offset % 4 != 0</code> (7 mod 4 = 3).</li>\n<li>Serialisierer injiziert $4 - 3 = 1$ Padding-Byte (Default: <code>0x00</code>) in den Puffer; Schreibzeiger inkrementiert auf Offset 8.</li>\n<li><code>UINT32</code> wird ab Offset 8 geschrieben; anschließendes <code>UINT64</code> wird ab Offset 12 geschrieben (12 mod 4 = 0, kein Padding).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Deserialisierung (Empfänger-Pfad, <code>SomeipXf_InvTransform</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Parser liest <code>Lengthfield (16Bit)</code> mit Wert <code>3</code> und konsumiert exakt 3 Bytes <code>uint8</code>.</li>\n<li>Vor dem Dekodieren des nachfolgenden Signals (<code>UINT32</code>) berechnet der Parser die erwartete Alignment-Grenze (32 Bit) und überspringt das Padding-Byte (Offset 7).</li>\n<li>Lesezeiger springt direkt auf Offset 8 zur Extraktion des <code>UINT32</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Längenfeld-Semantik:</strong> Das Padding-Byte zählt <strong>nicht</strong> zur Nutzdatenlänge des dynamischen Arrays. Der Wert im <code>Lengthfield (16Bit)</code> muss strikt <code>3</code> sein (nicht <code>4</code>). Ein Mitzählen von Alignment-Bytes im Längenfeld verletzt die SOME/IP-Spezifikation (<code>PRS_SOMEIPProtocol</code>).</li>\n<li><strong>Interoperabilität & ARXML-Konsistenz:</strong> Sender und Empfänger (Classic Platform SWC, Adaptive Platform Service Instance via <code>ara::com</code> oder Linux-Third-Party-Stacks wie <code>vsomeip</code>) müssen identische <code>SomeipTransformationProps.alignment</code>-Werte aufweisen. Weicht die Konfiguration ab (z. B. Sender ohne Alignment/<code>0</code>, Empfänger mit <code>32 Bit</code>), verschieben sich alle nachfolgenden Signale um 1 Byte, was zu schwer lokalisierbaren Deserialisierungs- und Datendefekten führt.</li>\n<li><strong>MCU-Architektur & Performance:</strong> 32-Bit- und 64-Bit-Mikrocontroller (z. B. Infineon AURIX TC3xx/TC4xx, ARM Cortex-R/Cortex-A) profitieren bei 32-Bit-ausgerichtetem Wire-Format von reduzierten Shift-/Maskierungsoperationen. Für hardwarebeschleunigten Zero-Copy-Zugriff muss zusätzlich sichergestellt werden, dass der Start des Ethernet-Payloads (nach IP/UDP- bzw. TCP- und SOME/IP-Header) im RAM 32-Bit-aligned allokiert ist.</li>\n<li><strong>Padding-Byte-Inhalt:</strong> Gemäß SOME/IP-Standard ist der Inhalt von Padding-Bytes senderseitig mit Nullen (<code>0x00</code>) zu belegen; empfängerseitig müssen die Padding-Bytes ignoriert und dürfen nicht auf statische Werte validiert werden.</li>\n</ul>"}], "trans": [{"from": "FIG-ca6ab24fd67057a1", "to": "FIG-dfcce4d31b876bf1", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-dfcce4d31b876bf1", "to": "FIG-bdfb59c77a572ecf", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-bdfb59c77a572ecf", "to": "FIG-8efaf0c350863cb2", "fr": "R20-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8efaf0c350863cb2", "to": "FIG-be371d2e6582e11d", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-be371d2e6582e11d", "to": "FIG-8efaf0c350863cb2", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8efaf0c350863cb2", "to": "FIG-421ce26007412e4d", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
